import type { Metadata } from "next";
import { locales, type Locale } from "@/lib/i18n";

// Production origin. www.brikvent.com redirects here (Vercel domain setting).
export const siteUrl = "https://brikvent.com";

// Link preview image, generated by app/opengraph-image.tsx.
export const shareImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Brikvent: the all-in-one commerce app for Bangladesh",
};

// "/signup" → { en: "/en/signup", bn: "/bn/signup", "x-default": "/en/signup" }
export function languageAlternates(path: string) {
  const languages: Record<string, string> = {};
  for (const lang of locales) languages[lang] = `/${lang}${path}`;
  languages["x-default"] = `/en${path}`;
  return languages;
}

// Canonical, hreflang, Open Graph and X card for one page. Every page sets
// its own openGraph, because a child's openGraph replaces the layout's
// whole object (title, url and image included).
export function pageMetadata({
  lang,
  path,
  title,
  description,
  canonicalPath = path,
}: {
  lang: Locale;
  // Path after the locale: "" for home, "/about", "/signup", ...
  path: string;
  // Page title without the "| Brikvent" suffix the layout template adds.
  title: string;
  description: string;
  // For duplicate pages that point search engines at another path.
  canonicalPath?: string;
}): Metadata {
  const url = `/${lang}${canonicalPath}`;
  return {
    description,
    alternates: { canonical: url, languages: languageAlternates(canonicalPath) },
    openGraph: {
      title,
      description,
      url,
      siteName: "Brikvent",
      type: "website",
      locale: lang === "bn" ? "bn_BD" : "en_US",
      alternateLocale: lang === "bn" ? "en_US" : "bn_BD",
      images: [shareImage],
    },
    twitter: { card: "summary_large_image", title, description, images: [shareImage] },
  };
}

// Serialises schema.org data for a <script type="application/ld+json">,
// escaping "<" so text can never close the script tag.
export const jsonLd = (data: unknown) => JSON.stringify(data).replace(/</g, "\\u003c");
